{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket has no logging",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket 'my-tf-test-bucket-ggff' does not have logging enabled, making it difficult to track access and changes to the bucket."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 Bucket has no versioning",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket 'my-tf-test-bucket-ggff' does not have versioning enabled, which means deleted or overwritten objects cannot be recovered."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"b\" {\n  bucket = \"my-tf-test-bucket-ggff\"\n  acl    = \"private\"\n\n  versioning {\n    enabled = true\n  }\n\n  logging {\n    target_bucket = \"my-tf-test-bucket-ggff-logs\"\n    target_prefix = \"/logs/\"\n  }\n}",
  "fix_summary": "Enabled versioning on the S3 bucket and added logging configuration to track access and changes."
}
